# Rebuilds Goodr/DOCUMENT-INDEX.md from the documents in the numbered folders.
# Run from the Goodr folder:  powershell -ExecutionPolicy Bypass -File scripts/doc-builders/build_document_index.ps1
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$EM = [string][char]0x2014; $enc = New-Object Text.UTF8Encoding($false)
function Info($f) {
  $lines = [IO.File]::ReadAllLines($f.FullName, [Text.Encoding]::UTF8)
  $title = ($lines[0] -replace '^#\s*', '' -replace "^[A-Z]+-\d+\s*$EM\s*", '').Trim()
  $status = ''; foreach ($l in $lines | Select-Object -First 14) { if ($l -match '^\| \*\*Status\*\* \| (.*) \|$') { $status = $matches[1] -replace '\]\(\.\./', ']('; } }
  $date = ''; foreach ($l in $lines | Select-Object -First 14) { if ($l -match '^\| \*\*(Date|Requested|Found)\*\* \| ([0-9-]{10})') { $date = $matches[2] } }
  [pscustomobject]@{ Id = ($f.BaseName -split '_')[0]; Title = $title; Status = $status; Date = $date; Rel = ($f.FullName.Substring($root.Length + 1) -replace '\\', '/') }
}
function NextFree($folder, $prefix) {
  $nums = Get-ChildItem "$root\$folder" -Filter "$prefix-*.md" | ForEach-Object { [int](($_.BaseName -split '_')[0] -replace "$prefix-", '') }
  if (-not $nums) { return "$prefix-001" }; return '{0}-{1:000}' -f $prefix, (($nums | Measure-Object -Maximum).Maximum + 1)
}
function Section($folder, $prefix, $cols) {
  $o = @("| ID | Document | $cols |", "|---|---|---|")
  foreach ($f in Get-ChildItem "$root\$folder" -Filter "$prefix-*.md" | Sort-Object Name) { $i = Info $f; $extra = if ($cols -eq 'Date') { $i.Date } else { $i.Status }; $o += "| $($i.Id) | [$($i.Title)]($($i.Rel)) | $extra |" }
  return $o
}
$md = @("# Goodr Project $EM Document Index", "",
 "Every project document, by folder and serial number. **Last updated:** $(Get-Date -Format 'yyyy-MM-dd') (generated by ``scripts/doc-builders/build_document_index.ps1``).", "",
 "## Naming convention", "``<PREFIX>-<3-digit serial>_<Short-Title-With-Hyphens>.md``, for example ``REQ-012_Cluster-Not-Updating-For-Sector-Only-Change.md``.", "",
 "| Folder | Prefix | What goes in it | Next free number |", "|---|---|---|---|",
 "| ``01-Instructions`` | $EM | How work is done. ``AI-Workflow.md`` and ``Coding-Standards.md`` are shared across projects and **read-only**; ``Project-Rules.md`` holds the Goodr rules | $EM |",
 "| ``02-Knowledge-Base`` | ``KB-`` | Background: overview, process, integrations, environment | $(NextFree '02-Knowledge-Base' 'KB') |",
 "| ``03-Requirements`` | ``REQ-`` | One per requirement: need, scope, acceptance criteria, open questions | $(NextFree '03-Requirements' 'REQ') |",
 "| ``04-Change-Records`` | ``CR-`` | One per change made to an org or the repo: what, when, deploy ID, verification, rollback | $(NextFree '04-Change-Records' 'CR') |",
 "| ``05-Conflicts`` | ``CON-`` | Problems faced, clashes, open risks | $(NextFree '05-Conflicts' 'CON') |",
 "| ``06-Deployment`` | ``DEP-`` | Production deployment documents, packages, checklists, QA | $(NextFree '06-Deployment' 'DEP') |",
 "| ``07-Technical`` | ``TECH-`` | Technical design, component inventories, secure configuration | $(NextFree '07-Technical' 'TECH') |", "",
 "**Rules:**",
 "- Numbers are never reused. A cancelled item keeps its number and is marked as such. REQ-027 to REQ-029 are not used.",
 "- An existing document is **updated** when its topic changes; a new topic gets a new number.",
 "- Every document links to its related REQ, CR, CON, DEP and TECH documents.",
 "- Every change to an org (a deploy, a Setup change or a data load) gets a CR the same day.", "",
 "## 01 $EM Instructions", "| File | Purpose |", "|---|---|",
 "| [AI-Workflow.md](01-Instructions/AI-Workflow.md) | Shared: workflows A, B and C; document structures (read-only) |",
 "| [Coding-Standards.md](01-Instructions/Coding-Standards.md) | Shared: rules every change must meet (read-only) |",
 "| [Project-Rules.md](01-Instructions/Project-Rules.md) | Goodr rules: orgs, change process, data, production, security, git |",
 "| [Developer-Onboarding.md](01-Instructions/Developer-Onboarding.md) | Start here: setup, reading order, first task, lessons learned |", "",
 "## 02 $EM Knowledge Base", "| ID | Document |", "|---|---|")
$kb = foreach ($f in Get-ChildItem "$root\02-Knowledge-Base" -Filter *.md) { $i = Info $f; $id = (Get-Content $f.FullName -TotalCount 6 -Encoding UTF8 | Select-String 'Document ID\*\* \| (KB-\d+)').Matches.Groups[1].Value; [pscustomobject]@{ Id = $id; Line = "| $id | [$($i.Title)]($($i.Rel)) |" } }
$md += ($kb | Sort-Object Id | ForEach-Object Line)
$md += "", "## 03 $EM Requirements"; $md += Section '03-Requirements' 'REQ' 'Status'
$md += "", "## 04 $EM Change Records"; $md += Section '04-Change-Records' 'CR' 'Date'
$md += "", "Supporting records in ``04-Change-Records/``:", "",
 "| Folder | Contents |", "|---|---|",
 "| [Before-Snapshots/](04-Change-Records/Before-Snapshots/) | Each component as it was in the org just **before** it was changed (dated folders) |",
 "| [Data-Changes/](04-Change-Records/Data-Changes/) | Data Loader files (V1 backfill, pilot, full update, rollback) and the record exports they were built from. **Sandbox data** |",
 "| [Org-Change-History/](04-Change-Records/Org-Change-History/Org-Change-History.md) | The orgs' own records: every deploy, deployed component and Setup Audit Trail entry since August 2026 (CSV + timeline). Regenerate with ``scripts/doc-builders/build_org_change_history.ps1`` |",
 "| [Session-Logs/](04-Change-Records/Session-Logs/) | What each Claude Code session did, when and why, and the user's requests (historical: uses the IDs and paths of that time) |"
$md += "", "## 05 $EM Conflicts"; $md += Section '05-Conflicts' 'CON' 'Status'
$md += "", "## 06 $EM Deployment"; $md += Section '06-Deployment' 'DEP' 'Status'
$md += "", "| Item | Contents |", "|---|---|",
 "| [Pre-Deployment-Checklist.md](06-Deployment/Pre-Deployment-Checklist.md) / [Post-Deployment-Checklist.md](06-Deployment/Post-Deployment-Checklist.md) | What to check before and after any deployment |",
 "| [Packages/](06-Deployment/Packages/) | Production packages (mdapi format), each with a ``_ROLLBACK`` package |",
 "| [Deployment-Documents/](06-Deployment/Deployment-Documents/) | Detailed deployment workbooks and the change-set component list |",
 "| [QA-Testing/](06-Deployment/QA-Testing/) | QA test scenarios, cluster/team reference, page-section checks |",
 "| [Post-Deployment-Verification/](06-Deployment/Post-Deployment-Verification/) | Evidence from sandbox verification and test runs |"
$md += "", "## 07 $EM Technical"; $md += Section '07-Technical' 'TECH' 'Status'
$md += "", "| Item | Contents |", "|---|---|",
 "| [Impact-Analysis/](07-Technical/Impact-Analysis/) | Where-used and impact workbooks for Sales Channel / Sector |",
 "| [Secure-Config-Templates/](07-Technical/Secure-Config-Templates/) | Credential records with ``SET_IN_ORG`` placeholders (see TECH-007) |"
[IO.File]::WriteAllText("$root\DOCUMENT-INDEX.md", ($md -join "`n") + "`n", $enc)
"DOCUMENT-INDEX.md written"
